// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import { config } from "dotenv";
// override: true hace que el .env local gane sobre variables ya seteadas
// (como los secretos enmascarados "****xxx" que inyecta Netlify en builds locales)
config({ override: true });
import { defineConfig } from "prisma/config";

// La CLI de Prisma (migrate deploy/dev/status) necesita la conexión DIRECTA a
// Neon: el pooler (PgBouncer) no soporta los advisory locks que usa migrate.
// En Netlify DATABASE_URL apunta al host "-pooler", así que aquí lo quitamos.
// La app en runtime NO usa este archivo — usa el adapter en src/lib/prisma.ts.
//
// NOTA: Netlify puede inyectar variables del sitio que sobreescriben el .env.
// Si DIRECT_DATABASE_URL tiene un valor inválido (sin prefijo postgresql://)
// lo ignoramos y caemos a DATABASE_URL para evitar el error P1013.
function toDirectUrl(raw: string): string {
  const cleaned = raw.replace("-pooler", "")
  return (cleaned.startsWith("postgresql://") || cleaned.startsWith("postgres://"))
    ? cleaned
    : ""
}

const directUrl =
  toDirectUrl(process.env["DIRECT_DATABASE_URL"] || "") ||
  toDirectUrl(process.env["DATABASE_URL"] || "")

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: directUrl,
  },
});
